    /// <summary>
    /// Modify based on the user selected to InventLocation
    /// </summary>
    /// <param name="sender">Form datasource</param>
    /// <param name="e">Data field</param>
    [FormDataFieldEventHandler(formDataFieldStr(InventJournalTransfer, InventDimReceipt, InventLocationId), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void ToInventLocationId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormRun             fr                  = sender.datasource().formRun();
        InventDim           inventDim           = fr.dataSource(formdatasourcestr(InventJournalTransfer, InventDimReceipt)).cursor();
        InventJournalTrans  inventJournalTrans  = fr.dataSource(formDataSourceStr(InventJournalTransfer, InventJournalTrans)).cursor();

        inventJournalTrans.toDimensionDefault(inventJournalTrans.inventJournalTable(), inventDim);
    }

